/**
 * Permanently removes rows archived longer ago than the plan's `retentionDays`.
 *
 * Must call (do not reimplement): getPlanLimits, isArchived
 */
import { getPlanLimits } from "@/config/plan-limits";
import { createLogger } from "@/lib/logger";
import { isArchived } from "@/lib/soft-delete";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

const ORG_BATCH = 25;
const PAGE_SIZE = 100;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

const logger = createLogger("cleanup-archived-job");

/**
 * The retention sweep. Soft-deleted rows are kept for as long as the plan
 * promises and no longer: the cut-off comes from `retentionDays`, so an
 * enterprise tenant keeps years of history where a free one keeps a month.
 *
 * Only the search documents are actually dropped here — the issue rows stay,
 * because the audit log still points at them — while the audit rows past the
 * window are purged outright.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org) continue;

      const { retentionDays } = getPlanLimits(org.plan);
      const cutoff = toIsoTimestamp(
        new Date(now.getTime() - retentionDays * MS_PER_DAY),
      );

      const archived = await issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor: null,
        includeArchived: true,
      });

      for (const issue of archived.items) {
        if (!isArchived(issue)) continue;
        if (issue.archivedAt === null || issue.archivedAt > cutoff) continue;

        await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
        result.processed += 1;
      }

      try {
        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
        result.processed += purged;
      } catch (error) {
        result.failed += 1;
        logger.error("activity purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
/**
 * Wires every subscriber at process start. Called once from `src/instrumentation.ts`; the only module that knows the full listener set.
 *
 * Must call (do not reimplement): subscribe, registerActivityListeners, registerSearchListeners, registerUsageListeners, registerWebhookListeners
 */
import { subscribe } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import { enqueue } from "@/server/jobs/queue";
import { toIsoTimestamp } from "@/types/common";
import { registerActivityListeners } from "./activity-service";
import { registerSearchListeners } from "./search-service";
import { registerUsageListeners } from "./usage-service";
import { registerWebhookListeners } from "./webhook-service";
import type { Unsubscribe } from "@/types/event";

/**
 * Importing this module also loads `notification-service` transitively, which
 * attaches the notification fan-out on first import — that hub has no
 * `register*` entry point of its own.
 */
import "./notification-service";

const logger = createLogger("event-registry");

/** Non-null between `registerEventHandlers()` and `unregisterEventHandlers()`. */
let detach: Unsubscribe | null = null;

/**
 * Attaches every subscriber exactly once. Idempotent: `instrumentation.ts`
 * runs per server process, but a hot reload in dev can call it again and must
 * not double-deliver every event.
 */
export function registerEventHandlers(): void {
  if (detach !== null) return;

  const offs: Unsubscribe[] = [
    registerActivityListeners(),
    registerSearchListeners(),
    registerUsageListeners(),
    registerWebhookListeners(),
    registerDigestBridge(),
  ];

  detach = () => {
    for (const off of offs) off();
  };

  logger.info("event handlers registered", { groups: offs.length });
}

export function unregisterEventHandlers(): void {
  detach?.();
  detach = null;
}

/**
 * The one piece of wiring that belongs to no single service: turning a
 * `digest.due` event into a queued job. Keeping it here rather than inside
 * `DigestService` stops the service layer from depending on the job layer.
 */
function registerDigestBridge(): Unsubscribe {
  return subscribe("digest.due", (payload) => {
    enqueue({
      id: `digest:${payload.orgId}:${payload.recipientId}`,
      kind: "digest-email",
      runAt: toIsoTimestamp(new Date()),
      attempts: 0,
      payload: {
        orgId: payload.orgId,
        recipientId: payload.recipientId,
        windowStart: payload.windowStart,
      },
    });
  });
}

/**
 * Issue rows: the widest query surface in the app. Every method takes `orgId` first and honours `IssueFilter.includeArchived`.
 *
 * Must call (do not reimplement): archivePatch, restorePatch, shouldFilterArchived
 */
import {
  and,
  count,
  desc,
  eq,
  inArray,
  isNotNull,
  isNull,
  like,
  lt,
  or,
  sql,
} from "drizzle-orm";
import { newId } from "@/lib/id";
import {
  archivePatch,
  restorePatch,
  shouldFilterArchived,
} from "@/lib/soft-delete";
import { attachments, comments, getDb, issueLabels, issues } from "@/server/db";
import { ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toIssue } from "./_mappers";
import { listLabelsForIssues } from "./label-repository";
import type {
  CreateIssueInput,
  IssueFilterInput,
  UpdateIssueInput,
} from "@/schemas/issue";
import type {
  ArchiveScope,
  IsoTimestamp,
  IssueId,
  LabelId,
  OrgId,
  Page,
  ProjectId,
  UserId,
} from "@/types/common";
import type {
  Issue,
  IssueBoardColumn,
  IssueStatus,
  IssueWithRelations,
} from "@/types/issue";
import type { SQL } from "drizzle-orm";

/** Statuses whose entry stamps `completed_at`; leaving one clears it again. */
const TERMINAL_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

export async function findIssueById(
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue | null> {
  const row = getDb()
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();
  if (!row) return null;

  const labels = await listLabelsForIssues(orgId, [row.id as IssueId]);
  return toIssue(row, (labels[row.id] ?? []).map((label) => label.id));
}

export async function findIssueByNumber(
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): Promise<Issue | null> {
  const row = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        eq(issues.number, issueNumber),
      ),
    )
    .get();
  return row ? toIssue(row) : null;
}

/** Builds the shared predicate list behind `listIssues` and its count. */
function issueFilters(input: IssueFilterInput): readonly SQL[] {
  const scope: ArchiveScope = shouldFilterArchived(input)
    ? {}
    : { includeArchived: true };

  return compact(
    orgPredicate(issues.orgId, input.orgId),
    livePredicate(issues.archivedAt, scope),
    input.projectId === undefined
      ? undefined
      : eq(issues.projectId, input.projectId),
    input.status === undefined || input.status.length === 0
      ? undefined
      : inArray(issues.status, [...input.status]),
    input.priority === undefined || input.priority.length === 0
      ? undefined
      : inArray(issues.priority, [...input.priority]),
    input.assigneeId === undefined
      ? undefined
      : input.assigneeId === null
        ? isNull(issues.assigneeId)
        : eq(issues.assigneeId, input.assigneeId),
    input.authorId === undefined
      ? undefined
      : eq(issues.authorId, input.authorId),
    input.dueBefore === undefined ? undefined : lt(issues.dueAt, input.dueBefore),
    input.query === undefined
      ? undefined
      : or(
          like(issues.title, `%${input.query}%`),
          like(issues.description, `%${input.query}%`),
        ),
    input.labelIds === undefined || input.labelIds.length === 0
      ? undefined
      : inArray(
          issues.id,
          getDb()
            .select({ id: issueLabels.issueId })
            .from(issueLabels)
            .where(
              and(
                orgPredicate(issueLabels.orgId, input.orgId),
                inArray(issueLabels.labelId, [...input.labelIds]),
              ),
            ),
        ),
  );
}

export async function listIssues(
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  const db = getDb();
  const filters = issueFilters(input);
  const sort = { sortColumn: issues.createdAt, idColumn: issues.id };

  const total = db
    .select({ value: count() })
    .from(issues)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(issues)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(issues.createdAt), desc(issues.id))
    .limit(probeLimit(input.limit))
    .all();

  const labels = await listLabelsForIssues(
    input.orgId,
    rows.map((row) => row.id as IssueId),
  );

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
    (row) => ({ id: row.id, sortValue: row.createdAt }),
  );
}

/**
 * The list view needs comment and attachment counts per row. Two grouped
 * queries beat N+1 round trips, so the counts are folded in afterwards.
 */
export async function listIssuesWithRelations(
  input: IssueFilterInput,
): Promise<Page<IssueWithRelations>> {
  const db = getDb();
  const page = await listIssues(input);
  const ids = page.items.map((issue) => issue.id);
  if (ids.length === 0) {
    return { items: [], nextCursor: page.nextCursor, total: page.total };
  }

  const commentCounts = db
    .select({ issueId: comments.issueId, value: count() })
    .from(comments)
    .where(
      and(
        orgPredicate(comments.orgId, input.orgId),
        inArray(comments.issueId, [...ids]),
        isNull(comments.archivedAt),
      ),
    )
    .groupBy(comments.issueId)
    .all();

  const attachmentCounts = db
    .select({ issueId: attachments.issueId, value: count() })
    .from(attachments)
    .where(
      and(
        orgPredicate(attachments.orgId, input.orgId),
        inArray(attachments.issueId, [...ids]),
      ),
    )
    .groupBy(attachments.issueId)
    .all();

  const labels = await listLabelsForIssues(input.orgId, ids);
  const commentsBy = new Map(commentCounts.map((r) => [r.issueId, r.value]));
  const attachmentsBy = new Map(
    attachmentCounts.map((r) => [r.issueId, r.value]),
  );

  return {
    items: page.items.map((issue) => ({
      issue,
      labels: labels[issue.id] ?? [],
      commentCount: commentsBy.get(issue.id) ?? 0,
      attachmentCount: attachmentsBy.get(issue.id) ?? 0,
    })),
    nextCursor: page.nextCursor,
    total: page.total,
  };
}

/** One column per status, in `ISSUE_STATUSES` order, live rows only. */
export async function listBoardColumns(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly IssueBoardColumn[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(desc(issues.updatedAt))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );

  return ISSUE_STATUSES.map((status) => {
    const column = rows
      .filter((row) => row.status === status)
      .map((row) => toIssue(row, (labels[row.id] ?? []).map((l) => l.id)));
    return { status, issues: column, total: column.length };
  });
}

export async function countIssues(
  orgId: OrgId,
  projectId: ProjectId,
  scope: ArchiveScope = {},
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, scope),
        ),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  return (row?.value ?? 0) + 1;
}

export async function insertIssue(
  input: CreateIssueInput,
  authorId: UserId,
  issueNumber: number,
): Promise<Issue> {
  const stamp = toIsoTimestamp(new Date());
  const db = getDb();

  const row = db
    .insert(issues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      number: issueNumber,
      title: input.title,
      description: input.description,
      status: input.status,
      priority: input.priority,
      authorId,
      assigneeId: input.assigneeId,
      parentId: input.parentId,
      estimate: input.estimate,
      dueAt: input.dueAt,
      startedAt: null,
      completedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  if (input.labelIds.length > 0) {
    db.insert(issueLabels)
      .values(
        input.labelIds.map((labelId) => ({
          orgId: input.orgId,
          issueId: row.id,
          labelId,
        })),
      )
      .run();
  }

  return toIssue(row, input.labelIds);
}

export async function updateIssue(input: UpdateIssueInput): Promise<Issue> {
  const db = getDb();
  const row = db
    .update(issues)
    .set({
      ...(input.title === undefined ? {} : { title: input.title }),
      ...(input.description === undefined
        ? {}
        : { description: input.description }),
      ...(input.priority === undefined ? {} : { priority: input.priority }),
      ...(input.estimate === undefined ? {} : { estimate: input.estimate }),
      ...(input.dueAt === undefined ? {} : { dueAt: input.dueAt }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(issues.orgId, input.orgId),
        eq(issues.id, input.issueId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${input.issueId} not found`);

  if (input.labelIds !== undefined) {
    db.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, input.orgId),
          eq(issueLabels.issueId, input.issueId),
        ),
      )
      .run();
    if (input.labelIds.length > 0) {
      db.insert(issueLabels)
        .values(
          input.labelIds.map((labelId: LabelId) => ({
            orgId: input.orgId,
            issueId: input.issueId,
            labelId,
          })),
        )
        .run();
    }
  }

  const labels = await listLabelsForIssues(input.orgId, [input.issueId]);
  return toIssue(row, (labels[input.issueId] ?? []).map((label) => label.id));
}

/** Status transitions maintain `started_at` / `completed_at` bookkeeping. */
export async function setIssueStatus(
  orgId: OrgId,
  issueId: IssueId,
  status: IssueStatus,
): Promise<Issue> {
  const stamp = toIsoTimestamp(new Date());
  const current = getDb()
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();

  if (!current) throw new Error(`Issue ${issueId} not found`);

  const row = getDb()
    .update(issues)
    .set({
      status,
      startedAt:
        status === "in_progress" && current.startedAt === null
          ? stamp
          : current.startedAt,
      completedAt: TERMINAL_STATUSES.includes(status) ? stamp : null,
      updatedAt: stamp,
    })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  return toIssue(row);
}

export async function setIssueAssignee(
  orgId: OrgId,
  issueId: IssueId,
  assigneeId: UserId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ assigneeId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

export async function archiveIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set(archivePatch())
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

export async function restoreIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set(restorePatch())
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

/** Cascade behind `ProjectService.archiveProject`; returns the row count. */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning({ id: issues.id })
    .all();

  return rows.length;
}

/** Live, still-open issues whose due date has passed. Drives the overdue job. */
export async function listOverdueIssues(
  orgId: OrgId,
  now: IsoTimestamp,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          livePredicate(issues.archivedAt, {}),
          isNotNull(issues.dueAt),
          lt(issues.dueAt, now),
          inArray(issues.status, ["backlog", "todo", "in_progress", "in_review"]),
        ),
      ),
    )
    .orderBy(issues.dueAt)
    .all();

  return rows.map((row) => toIssue(row));
}

/**
 * Query-time search plus the write-time index maintenance driven by `search.reindex_requested`.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, consumeRateLimit
 */
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { orgResource } from "./_support";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchSubjectKind } from "@/server/repositories/search-repository";
import type { Comment } from "@/types/comment";
import type { OrgId, Page } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Project } from "@/types/project";

export type SearchHit = {
  kind: SearchSubjectKind;
  id: string;
  title: string;
  snippet: string;
  href: string;
};

/** Characters of surrounding context kept on either side of a match. */
const SNIPPET_RADIUS = 60;

/** Token bucket protecting the index from query bursts. */
const SEARCH_QUERY_BUCKET = "search:query";

/**
 * Runs a query against the denormalised index. Field-scoped syntax
 * (`status:done`) is an `advanced_search` feature, so a query containing a
 * colon is rejected for plans that do not include it rather than silently
 * being treated as literal text.
 */
export async function search(
  actor: Actor,
  input: SearchQueryInput,
): Promise<Page<SearchHit>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "issue:read", orgResource(input.orgId));

  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Search rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = await orgRepo.findOrgById(input.orgId);
  const advanced = isEnabled("advanced_search", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  if (input.q.includes(":") && !advanced) {
    throw new Error("Field-scoped search is not included in this plan");
  }

  const page = await searchRepo.searchDocuments(input);

  return {
    items: page.items.map((row) => ({
      kind: row.subjectKind,
      id: row.subjectId,
      title: row.content.split("\n")[0] ?? row.subjectId,
      snippet: snippetAround(row.content, input.q),
      href: hrefFor(row.subjectKind, row.subjectId),
    })),
    nextCursor: page.nextCursor,
    total: page.total,
  };
}

export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\n"),
    issue.projectId,
  );
}

export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    null,
  );
}

export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\n"),
    project.id,
  );
}

export async function removeFromIndex(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
}

/**
 * Keeps the index in step with writes. Every handler re-reads the row rather
 * than trusting the event payload, so a partially-applied write can never be
 * indexed as if it had succeeded.
 */
export function registerSearchListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (issue) await indexIssue(payload.orgId, issue);
    }),
    subscribe("issue.updated", async (payload) => {
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (issue) await indexIssue(payload.orgId, issue);
    }),
    subscribe("issue.archived", async (payload) => {
      await removeFromIndex(payload.orgId, "issue", payload.issueId);
    }),
    subscribe("comment.created", async (payload) => {
      const comment = await commentRepo.findCommentById(
        payload.orgId,
        payload.commentId,
      );
      if (comment) await indexComment(payload.orgId, comment);
    }),
    subscribe("comment.deleted", async (payload) => {
      await removeFromIndex(payload.orgId, "comment", payload.commentId);
    }),
    subscribe("project.created", async (payload) => {
      const project = await projectRepo.findProjectById(
        payload.orgId,
        payload.projectId,
      );
      if (project) await indexProject(payload.orgId, project);
    }),
    subscribe("project.archived", async (payload) => {
      await removeFromIndex(payload.orgId, "project", payload.projectId);
    }),
    subscribe("search.reindex_requested", async (payload) => {
      if (payload.subjectKind !== "issue") return;
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.subjectId as Issue["id"],
      );
      if (issue) await indexIssue(payload.orgId, issue);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

function hrefFor(kind: SearchSubjectKind, subjectId: string): string {
  switch (kind) {
    case "issue":
      return `/issues/${subjectId}`;
    case "comment":
      return `/comments/${subjectId}`;
    case "project":
      return `/projects/${subjectId}`;
  }
}

function snippetAround(content: string, query: string): string {
  const at = content.toLowerCase().indexOf(query.toLowerCase());
  if (at < 0) return content.slice(0, SNIPPET_RADIUS * 2);

  const start = Math.max(0, at - SNIPPET_RADIUS);
  const end = Math.min(content.length, at + query.length + SNIPPET_RADIUS);
  return `${start > 0 ? "…" : ""}${content.slice(start, end)}${
    end < content.length ? "…" : ""
  }`;
}
/**
 * Recomputes the usage counters that every `LimitCheck` compares against.
 *
 * Must call (do not reimplement): assertOrgScope, subscribe, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { emit, subscribe } from "@/lib/event-bus";
import { assertOrgScope } from "@/lib/tenant";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";
import type { OrganizationUsage } from "@/types/organization";

/** Fraction of a quota at which the "approaching limit" event fires. */
const WARN_THRESHOLD = 0.9;

export async function getUsage(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationUsage> {
  assertOrgScope(actor, orgId);
  return usageRepo.getUsage(orgId);
}

/**
 * Full recount from the source tables. Called by the rollup job and by every
 * event that could have moved a counter — after recounting, the seat and
 * project totals are checked against the plan so a breach surfaces as an
 * event rather than waiting for the next write to be rejected.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const usage = await usageRepo.recomputeUsage(orgId);
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return usage;

  const limits = getPlanLimits(org.plan);

  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
    await emit("billing.limit_exceeded", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      resource: "seats",
      limit: limits.seats,
      used: usage.seatsUsed,
    });
  }

  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
    await emit("billing.limit_exceeded", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      resource: "projects",
      limit: limits.projects,
      used: usage.projectsUsed,
    });
  }

  return usage;
}

/**
 * Every event that changes a counted resource nudges the cache. The deltas are
 * cheap; the periodic rollup is what corrects any drift they accumulate.
 */
export function registerUsageListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
    }),
    subscribe("issue.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
    }),
    subscribe("project.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
    }),
    subscribe("project.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, {
        projectsUsed: -1,
        issuesUsed: -payload.issuesArchived,
      });
    }),
    subscribe("member.joined", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
    }),
    subscribe("member.removed", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}
/**
 * The `organization_usage` counters read by every plan-limit check.
 */
import { and, count, eq, isNull, sql } from "drizzle-orm";
import {
  attachments,
  getDb,
  issues,
  members,
  organizationUsage,
  projects,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toUsage } from "./_mappers";
import { brandId } from "./_mappers";
import type { OrgId } from "@/types/common";
import type { OrganizationUsage } from "@/types/organization";

const BYTES_PER_MB = 1024 * 1024;

/**
 * Reads the cached counters, materialising a zeroed row the first time an org
 * is asked about. A limit check must never fail because the rollup has not run.
 */
export async function getUsage(orgId: OrgId): Promise<OrganizationUsage> {
  const row = getDb()
    .select()
    .from(organizationUsage)
    .where(eq(organizationUsage.orgId, orgId))
    .get();

  if (row) return toUsage(row);

  const created = getDb()
    .insert(organizationUsage)
    .values({ orgId, measuredAt: toIsoTimestamp(new Date()) })
    .returning()
    .get();

  return toUsage(created);
}

/**
 * Recounts every dimension from the source tables and rewrites the cache.
 * Called by the rollup job and after any bulk change that would drift.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const db = getDb();

  const seats = db
    .select({ value: count() })
    .from(members)
    .where(
      and(
        eq(members.orgId, orgId),
        eq(members.status, "active"),
        isNull(members.archivedAt),
      ),
    )
    .get();

  const projectCount = db
    .select({ value: count() })
    .from(projects)
    .where(and(eq(projects.orgId, orgId), isNull(projects.archivedAt)))
    .get();

  const issueCount = db
    .select({ value: count() })
    .from(issues)
    .where(and(eq(issues.orgId, orgId), isNull(issues.archivedAt)))
    .get();

  const bytes = db
    .select({ value: sql<number | null>`sum(${attachments.sizeBytes})` })
    .from(attachments)
    .where(eq(attachments.orgId, orgId))
    .get();

  const next = {
    orgId,
    seatsUsed: seats?.value ?? 0,
    projectsUsed: projectCount?.value ?? 0,
    issuesUsed: issueCount?.value ?? 0,
    storageMbUsed: Math.ceil((bytes?.value ?? 0) / BYTES_PER_MB),
    measuredAt: toIsoTimestamp(new Date()),
  };

  const row = db
    .insert(organizationUsage)
    .values(next)
    .onConflictDoUpdate({ target: organizationUsage.orgId, set: next })
    .returning()
    .get();

  return toUsage(row);
}

/**
 * Cheap delta applied on the write path so a quota check right after a create
 * sees the new number without waiting for the rollup.
 */
export async function incrementUsage(
  orgId: OrgId,
  patch: Partial<
    Pick<
      OrganizationUsage,
      "seatsUsed" | "projectsUsed" | "issuesUsed" | "storageMbUsed"
    >
  >,
): Promise<OrganizationUsage> {
  const current = await getUsage(orgId);

  const row = getDb()
    .update(organizationUsage)
    .set({
      seatsUsed: current.seatsUsed + (patch.seatsUsed ?? 0),
      projectsUsed: current.projectsUsed + (patch.projectsUsed ?? 0),
      issuesUsed: current.issuesUsed + (patch.issuesUsed ?? 0),
      storageMbUsed: current.storageMbUsed + (patch.storageMbUsed ?? 0),
      measuredAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizationUsage.orgId, orgId))
    .returning()
    .get();

  return toUsage(row);
}

/** The rollup job's work list: the oldest measurements first. */
export async function listOrgIdsForRollup(
  limit: number,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ orgId: organizationUsage.orgId })
    .from(organizationUsage)
    .orderBy(organizationUsage.measuredAt)
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => brandId<OrgId>(row.orgId));
}

